{"code":"def transform(grid):
    from collections import Counter
    c=Counter(x for row in grid for x in row)
    singles=[x for x,n in c.items() if n==1]
    if singles:
        return [[singles[0]]]
    # for the small corner-pattern case, choose the corner color differing from the other three
    corners=[grid[0][0],grid[0][-1],grid[-1][0],grid[-1][-1]]
    for x in corners:
        if corners.count(x)==1:
            return [[x]]
    return [[grid[-1][-1]]]"}

